def transform(grid):
    # Insert color 2 into every one-cell horizontal gap between two occurrences
    # of the repeated motif color; this is the pattern in all provided demos.
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c - 1] != row[c] and row[c + 1] == row[c - 1]:
                # The in-between cell is background, the two endpoints match.
                out[r][c] = 2
    return out

