from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for color in row:
            counts[color] = counts.get(color, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    seen = set()
    q = deque()
    # The top and side edges identify exterior background. The lower edge may
    # be closed by a drawn outline and thus is not automatically exterior.
    for c in range(w):
        if grid[0][c] == background and (0, c) not in seen:
            seen.add((0, c)); q.append((0, c))
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == background and (r, c) not in seen:
                seen.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and
                    grid[nr][nc] == background and (nr, nc) not in seen):
                seen.add((nr, nc)); q.append((nr, nc))
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background and (r, c) not in seen:
                out[r][c] = 4
    return out

