def transform(grid):
    out = [row[:] for row in grid]
    # The lower 2-row motif repeats the upper motif but is truncated on the
    # right; mark the omitted foreground continuation in color 1.
    h, w = len(grid), len(grid[0])
    nonempty = [r for r, row in enumerate(grid) if any(v != 0 for v in row)]
    if len(nonempty) >= 4:
