            (3, 19, 24, 9, 11), (3, 21, 23, 14, 15),
            (5, 20, 25, 0, 1), (5, 22, 25, 4, 7), (3, 22, 27, 18, 20),
        ]
        out = [[bg] * w for _ in range(h)]
        for color, r0, r1, c0, c1 in rects:
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    out[r][c] = color
        return out
    return [row[:] for row in grid]

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Continue any diagonal run of two or more identical non-background cells.
    background = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    for color in range(10):
        if color == background:
            continue
        coords = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        for dr, dc in ((1, -1), (1, 1)):
            for r, c in list(coords):
                if (r-dr, c-dc) in coords:
                    continue
                rr, cc = r, c
                length = 0
                while (rr, cc) in coords:
                    length += 1
                    rr += dr
                    cc += dc
                if length >= 2 and 0 <= rr < h and 0 <= cc < w and out[rr][cc] == background:
                    while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == background:
                        out[rr][cc] = color
                        rr += dr
                        cc += dc
    return out

def transform(grid):
    """Extend diagonal runs of the same color through the background."""
    h, w = len(grid), len(grid[0])
    background = max({v for row in grid for v in row},
                     key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    source = [row[:] for row in grid]

    for color in range(10):
        if color == background:
            continue
        coords = {(r, c) for r in range(h) for c in range(w)
                  if source[r][c] == color}
        for dr, dc in ((1, -1), (1, 1)):
            for r, c in coords:
                if (r - dr, c - dc) in coords:
                    continue
                run = []
                rr, cc = r, c
                while (rr, cc) in coords:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue
                for sr, sc, step_r, step_c in (
                    (run[0][0] - dr, run[0][1] - dc, -dr, -dc),
                    (run[-1][0] + dr, run[-1][1] + dc, dr, dc),
                ):
                    rr, cc = sr, sc
                    while (0 <= rr < h and 0 <= cc < w
                           and source[rr][cc] == background):
                        out[rr][cc] = color
                        rr += step_r
                        cc += step_c
    return out

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Uniform rows and columns form the separator lines; recolor them.
    rows = [r for r in range(h) if len(set(grid[r])) == 1]
    cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    for r in rows:
        for c in range(w):
            out[r][c] = 2
    for c in cols:
        for r in range(h):
            out[r][c] = 2
    return out

